type agreementNativeCodeDiagnosticSingle struct {
	Field, Index, Start int
	Body                string
	Diagnostics         []render.Diagnostic
}
type agreementNativeCodeDiagnosticWitness struct {
	Name, Body, Target, Selected    string
	Diagnostics, PrivateDiagnostics []render.Diagnostic
	Indices                         []int
	Singles                         []agreementNativeCodeDiagnosticSingle
}

type agreementNativeCodeDiagnosticOwner struct{ Field, Code int }

// All physical fields are retained before any diagnostic producer is selected.
func agreementNativeCodeDiagnosticPhysical(native agreementNativeOwnerSource, check *agreementNativeCheckSource, target string) ([]agreementNativeCodeDiagnosticOwner, bool) {
	if target == "" {
		return nil, false
	}
	var physical []agreementNativeCodeDiagnosticOwner
	used := map[graph.Span]bool{}
	for fi, f := range check.Fields {
		if !f.Code || f.Comment || f.Escaped || f.DefinitionOwner >= 0 || f.CodeOwner < 0 || !slices.Contains(f.Targets, target) {
			continue
		}
		if len(f.Targets) != 1 || used[f.Span] {
			return nil, false
		}
		at := -1
		for ci, code := range native.Code {
			if f.Span.Start >= code.Span.Start && f.Span.Stop <= code.Span.Stop && f.Span.Stop > f.Span.Start {
				if at >= 0 {
					return nil, false
				}
				at = ci
			}
		}
		if at < 0 || at != f.CodeOwner {
			continue
		}
		used[f.Span] = true
		physical = append(physical, agreementNativeCodeDiagnosticOwner{fi, at})
	}
	return physical, len(physical) > 0
}

func agreementNativeCodeDiagnosticPrivate(body, target string, owners []agreementNativeCodeDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	if target == "" || len(owners) == 0 || strings.Contains(body, "q") {
		return "", nil, false
	}
	private := []byte(body)
	var changes []agreementMixedRename
	used := map[int]bool{}
	for _, owner := range owners {
		if owner.Field < 0 || owner.Field >= len(check.Fields) || used[owner.Field] {
			return "", nil, false
		}
		used[owner.Field] = true
		f := check.Fields[owner.Field]
		if !f.Code || f.Comment || f.Escaped || f.DefinitionOwner >= 0 || f.CodeOwner != owner.Code || f.Span.Start < 0 || f.Span.Stop > len(body) || body[f.Span.Start:f.Span.Stop] != f.Word || !strings.HasPrefix(f.Word, "[[") || !strings.HasSuffix(f.Word, "]]") {
			return "", nil, false
		}
		inner := f.Word[2 : len(f.Word)-2]
		link, valid := graph.ParseWikilink(inner)
		if !valid || link.Target != target || strings.ContainsAny(inner, "[]\r\n") || strings.ContainsRune(inner, 96) {
			return "", nil, false
		}
		start := f.Span.Start + 2 + strings.Index(inner, target)
		stop := start + len(target)
		if start < f.Span.Start+2 || stop > f.Span.Stop-2 || body[start:stop] != target {
			return "", nil, false
		}
		replacement := strings.Repeat("q", len(target))
		copy(private[start:stop], replacement)
		changes = append(changes, agreementMixedRename{Field: owner.Field, Span: graph.Span{Start: start, Stop: stop}, Old: target, New: replacement})
	}
	return string(private), changes, true
}

// Each producer changes one diagnostic while the complete rendered page stays fixed.
func agreementNativeCodeDiagnosticProducers(t *testing.T, body, target string, native agreementNativeOwnerSource, check *agreementNativeCheckSource) (physicalFields, diagnosticFields []agreementNativeCodeDiagnosticOwner, targetChanges []agreementMixedRename, projectedBody string, valid bool) {
	t.Helper()
	physical, ok := agreementNativeCodeDiagnosticPhysical(native, check, target)
	if !ok {
		return nil, nil, nil, "", false
	}
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	tree := agreementNativeProseAddressTreeReading(body, nil)
	parts, pok := agreementCodeWindowParts(raw.HTML)
	if !pok {
		return nil, nil, nil, "", false
	}
	var owners []agreementNativeCodeDiagnosticOwner
	var changes []agreementMixedRename
	whole := []byte(body)
	used := map[int]bool{}
	for _, owner := range physical {
		private, oneChanges, valid := agreementNativeCodeDiagnosticPrivate(body, target, []agreementNativeCodeDiagnosticOwner{owner}, check)
		if !valid {
			continue
		}
		pr, pp := agreementIsolatedPage(t, agreementCase{Body: private})
		privateParts, validParts := agreementCodeWindowParts(pr.HTML)
		if !validParts || !cmp.Equal(native, agreementNativeOwnerReading(private)) || !cmp.Equal(tree, agreementNativeProseAddressTreeReading(private, nil)) || raw.HTML != pr.HTML || !cmp.Equal(page, pp) || !cmp.Equal(parts, privateParts) || len(raw.Diagnostics) != len(pr.Diagnostics) {
			continue
		}
		index := -1
		unique := true
		for di := range raw.Diagnostics {
			if cmp.Equal(raw.Diagnostics[di], pr.Diagnostics[di]) {
				continue
			}
			if index >= 0 {
				unique = false
				break
			}
			index = di
		}
		if !unique || index < 0 || used[index] {
			continue
		}
		a, b := raw.Diagnostics[index], pr.Diagnostics[index]
		change := oneChanges[0]
		if a.Kind != render.DiagWikilinkBroken || a.Target != target || b.Target != change.New || a.Kind != b.Kind || a.Section != b.Section || a.Block != b.Block || b.Message != strings.ReplaceAll(a.Message, "\""+target+"\"", "\""+change.New+"\"") {
			continue
		}
		used[index] = true
		owners = append(owners, owner)
		changes = append(changes, change)
		copy(whole[change.Span.Start:change.Span.Stop], change.New)
	}
	return physical, owners, changes, string(whole), len(owners) > 0
}

func agreementNativeCodeDiagnosticSource(body, target string) (*agreementNativeCodeDiagnosticSourceWitness, *agreementNativeCodeDiagnosticVariant, bool) {
	witnesses := agreementNativeCodeDiagnosticSources()
	for wi := range witnesses {
		w := &witnesses[wi]
		if w.Body != body {
			continue
		}
		for vi := range w.Variants {
			v := &w.Variants[vi]
			if v.Target == target {
				return w, v, true
			}
		}
		return nil, nil, false
	}
	return nil, nil, false
}

// Every changed diagnostic belongs to one declared native code field.
func agreementNativeCodeDiagnosticDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P0" || f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only" || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || f.Tuple.State != "wikilink-broken" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementNativeCodeDiagnosticWitnesses()
	for ri := range records {
		r := &records[ri]
		if c.Body != r.Body || f.Tuple.Target != r.Target {
			continue
		}
		if agreementSignature(f) != r.Selected || !cmp.Equal(diagnostics, r.Diagnostics) {
			return "", "", ""
		}
		w, v, found := agreementNativeCodeDiagnosticSource(c.Body, r.Target)
		if !found {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, pok := agreementCodeWindowParts(raw)
		physical, ok := agreementNativeCodeDiagnosticPhysical(native, &check, r.Target)
		private, changes, valid := agreementNativeCodeDiagnosticPrivate(c.Body, r.Target, v.Owners, &check)
		if !pok || !ok || !valid || len(v.Owners) != f.Multiplicity || len(r.Indices) != len(v.Owners) || !cmp.Equal(physical, v.Physical) || !cmp.Equal(changes, v.Changes) || private != v.Body || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementMixedCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}

